pm.test("Payout API returned an accepted response", function () {
  pm.expect([200, 201]).to.include(pm.response.code);
});

const response = pm.response.json();

pm.test("Payout batch ID exists", function () {
  pm.expect(response.batch_header).to.exist;
  pm.expect(response.batch_header.payout_batch_id).to.be.a("string");
});

pm.test("Initial batch status is valid", function () {
  const status = response.batch_header.batch_status;

  pm.expect([
    "PENDING",
    "PROCESSING",
    "SUCCESS",
    "DENIED"
  ]).to.include(status);
});

if (response.batch_header?.payout_batch_id) {
  pm.environment.set(
    "payout_batch_id",
    response.batch_header.payout_batch_id
  );

  console.log(
    "Payout batch ID:",
    response.batch_header.payout_batch_id
  );
}

pm.test("Payout status request succeeded", function () {
  pm.response.to.have.status(200);
});

const response = pm.response.json();

pm.test("Batch header exists", function () {
  pm.expect(response.batch_header).to.exist;
});

pm.test("Batch status is recognized", function () {
  pm.expect([
    "PENDING",
    "PROCESSING",
    "SUCCESS",
    "DENIED",
    "CANCELED"
  ]).to.include(response.batch_header.batch_status);
});

const items = response.items || [];

pm.test("At least one payout item is returned", function () {
  pm.expect(items.length).to.be.greaterThan(0);
});

if (items.length > 0) {
  const itemStatus = items[0].transaction_status;

  pm.test("First payout item has a recognized status", function () {
    pm.expect([
      "PENDING",
      "SUCCESS",
      "FAILED",
      "UNCLAIMED",
      "RETURNED",
      "BLOCKED",
      "REFUNDED",
      "REVERSED",
      "ONHOLD"
    ]).to.include(itemStatus);
  });

  console.log("Batch status:", response.batch_header.batch_status);
  console.log("Item status:", itemStatus);
}

