let response;

pm.test("Response body is valid JSON", function () {
  response = pm.response.json();
  pm.expect(response).to.be.an("object");
});

/*
 * A newly created PayPal order normally returns 201.
 * PayPal can return 200 when an idempotent request retrieves
 * the result of a previously processed request.
 */
pm.test("Order request succeeded", function () {
  pm.expect([200, 201]).to.include(pm.response.code);
});

pm.test("Order ID exists", function () {
  pm.expect(response.id).to.be.a("string");
  pm.expect(response.id.length).to.be.greaterThan(5);
});

/*
 * PayPal currently returned PAYER_ACTION_REQUIRED in your test.
 * CREATED may also appear depending on the request/response flow.
 */
pm.test("Order is waiting for buyer approval", function () {
  pm.expect([
    "CREATED",
    "PAYER_ACTION_REQUIRED"
  ]).to.include(response.status);
});

pm.test("Order intent is AUTHORIZE", function () {
  pm.expect(response.intent).to.eql("AUTHORIZE");
});

pm.test("Order amount is USD 10.00", function () {
  const amount = response.purchase_units?.[0]?.amount;

  pm.expect(amount).to.exist;
  pm.expect(amount.currency_code).to.eql("USD");
  pm.expect(amount.value).to.eql("10.00");
});

pm.test("This is the void-test vault", function () {
  const purchaseUnit = response.purchase_units?.[0];

  pm.expect(purchaseUnit).to.exist;
  pm.expect(purchaseUnit.reference_id).to.eql("vault-demo-002");
  pm.expect(purchaseUnit.custom_id).to.eql("vault-demo-002");
  pm.expect(purchaseUnit.invoice_id).to.eql(
    "vault-demo-002-void-001"
  );
});

const approvalLink = response.links?.find(function (link) {
  return link.rel === "payer-action" || link.rel === "approve";
});

pm.test("Buyer approval URL exists", function () {
  pm.expect(approvalLink).to.exist;
  pm.expect(approvalLink.href).to.be.a("string");
  pm.expect(approvalLink.href).to.include(
    "sandbox.paypal.com"
  );
});

pm.environment.set("order_id", response.id);

if (approvalLink) {
